function wordTier(chunk: Chunk, pane: 'left' | 'right'): 'live' | 'resolved' | 'ignored' {
  if (chunk.state === 'ignored') {
    return 'ignored';
  }
  if (chunk.state === 'manuallyEdited') {
    return 'resolved';
  }
  if (chunk.kind !== 'conflict') {
    return chunk.state === 'initial' ? 'live' : 'resolved';
