function setLintStatus(state: 'checking' | { errors: number; warnings: number }): void {
  if (!lintStatus) return;
  if (state === 'checking') {
    lintStatus.textContent = '…';
    lintStatus.className = 'mf-lint-status mf-lint-checking';
    return;
  }
  const { errors, warnings } = state;
  if (errors === 0 && warnings === 0) {
    lintStatus.textContent = '✓';
    lintStatus.className = 'mf-lint-status mf-lint-ok';
    lintStatus.title = 'No problems in the result';
  } else {
    const parts: string[] = [];
    if (errors > 0) parts.push(`${errors} error${errors === 1 ? '' : 's'}`);
    if (warnings > 0) parts.push(`${warnings} warning${warnings === 1 ? '' : 's'}`);
    lintStatus.textContent = `⚠ ${parts.join(', ')}`;
    lintStatus.className = errors > 0 ? 'mf-lint-status mf-lint-error' : 'mf-lint-status mf-lint-warning';
    lintStatus.title = 'Problems in the result (hover the squiggles for details)';
  }
}
