function applyLintMarkers(diagnostics: LintDiagnostic[]): void {
  if (!session) return;
  const model = session.panes.center.getModel();
  if (!model) return;
  const errors = diagnostics.filter((d) => d.severity === 'error').length;
  const warnings = diagnostics.filter((d) => d.severity !== 'error').length;
  const markers = diagnostics.map((d) => {
    const startLine = d.startLine + 1;
    const startColumn = d.startCharacter + 1;
    const endLine = d.endLine + 1;
    let endColumn = d.endCharacter + 1;
    if (startLine === endLine && endColumn <= startColumn) {
      endColumn = startColumn + 1; // zero-width diagnostics still need a visible squiggle
    }
    return {
      startLineNumber: startLine,
      startColumn,
      endLineNumber: endLine,
      endColumn,
      message: d.message,
      severity: d.severity === 'error'
        ? monaco.MarkerSeverity.Error
        : d.severity === 'warning'
          ? monaco.MarkerSeverity.Warning
          : monaco.MarkerSeverity.Info,
    };
  });
  monaco.editor.setModelMarkers(model, LINT_OWNER, markers);
  setLintStatus({ errors, warnings });
}
