/** Renders host diagnostics as squiggles in the center pane and updates the footer chip. */
function applyLintMarkers(diagnostics: LintDiagnostic[], unavailable: boolean): void {
  if (!session) {
    return;
  }
  const model = session.panes.center.getModel();
  if (!model) {
    return;
  }
  if (unavailable) {
    monaco.editor.setModelMarkers(model, LINT_OWNER, []);
    setLintStatus('unavailable');
    return;
  }
  const errors = diagnostics.filter((d) => d.severity === 'error').length;
  const warnings = diagnostics.filter((d) => d.severity !== 'error').length;
  const markers = diagnostics.map((d) => {
    const startLineNumber = d.startLine + 1;
    const startColumn = d.startCharacter + 1;
    const endLineNumber = d.endLine + 1;
    // Zero-width diagnostics (pure insertion points) still need a visible squiggle.
    const endColumn =
      startLineNumber === endLineNumber && d.endCharacter + 1 <= startColumn
        ? startColumn + 1
        : d.endCharacter + 1;
    return {
      startLineNumber,
      startColumn,
      endLineNumber,
      endColumn,
      message: d.message,
      severity:
        d.severity === 'error'
          ? monaco.MarkerSeverity.Error
          : d.severity === 'warning'
            ? monaco.MarkerSeverity.Warning
            : monaco.MarkerSeverity.Info,
    };
  });
  monaco.editor.setModelMarkers(model, LINT_OWNER, markers);
  setLintStatus({ errors, warnings });
}

function setLintStatus(state: 'checking' | 'unavailable' | { errors: number; warnings: number }): void {
  if (!lintStatus) {
    return;
  }
  if (state === 'checking') {
    lintStatus.textContent = '…';
    lintStatus.className = 'mf-lint-status mf-lint-checking';
    lintStatus.title = 'Checking the result for syntax errors';
    return;
  }
  if (state === 'unavailable') {
    lintStatus.textContent = 'lint: n/a';
    lintStatus.className = 'mf-lint-status mf-lint-unavailable';
    lintStatus.title = 'No linter available for this file type';
    return;
  }
  const { errors, warnings } = state;
  if (errors === 0 && warnings === 0) {
    lintStatus.textContent = '✓';
    lintStatus.className = 'mf-lint-status mf-lint-ok';
    lintStatus.title = 'No problems in the result';
    return;
  }
  const parts: string[] = [];
  if (errors > 0) {
    parts.push(`${errors} error${errors === 1 ? '' : 's'}`);
  }
  if (warnings > 0) {
    parts.push(`${warnings} warning${warnings === 1 ? '' : 's'}`);
  }
  lintStatus.textContent = `⚠ ${parts.join(' · ')}`;
  lintStatus.className = errors > 0 ? 'mf-lint-status mf-lint-error' : 'mf-lint-status mf-lint-warning';
  lintStatus.title = 'Problems in the result — hover a squiggle for details';
}"}

