private async lint(content: string): Promise<void> {
  const ext = extname(this.uri.fsPath);
  if (!ext) {
    this.post({ type: 'lintResult', payload: [], unavailable: true });
    return;
  }
  // Same directory as the real file, so relative imports and ESLint config resolution
  // behave exactly as they will once the merge is written. A unique, clearly-named file
  // keeps it from clashing with anything and it is deleted right after the check.
  const base = basename(this.uri.fsPath, ext);
  const nonce = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const name = `merge-forge-lint-${nonce}-${base}${ext}`;
  const uri = vscode.Uri.file(join(dirname(this.uri.fsPath), name));

  try {
    await vscode.workspace.fs.writeFile(uri, Buffer.from(content, 'utf8'));
    await vscode.workspace.openTextDocument(uri);
    const diagnostics = await this.collectDiagnostics(uri);
    this.post({ type: 'lintResult', payload: diagnostics.map(toLintDiagnostic) });
  } catch (error) {
    getOutputChannel().appendLine(`[warn] ${this.relativePath}: lint failed — ${String(error)}`);
    this.post({ type: 'lintResult', payload: [], unavailable: true });
  } finally {
    try {
      await vscode.workspace.fs.delete(uri, { useTrash: false });
    } catch {
      // Best-effort cleanup.
    }
  }
}
```

