import ts from 'typescript';

/**
 * Self-contained syntax check of the merged result. Runs in the webview, so it works
 * identically in the VS Code panel and the Tauri desktop app — no host/language-service
 * round-trip required. TypeScript's parser gives precise, multi-error diagnostics for
 * TS/JS/TSX/JSX; JSON is checked with JSON.parse. Everything else is "not supported".
 */

export interface SyntaxIssue {
  startLine: number;   // 0-based
  startCharacter: number;
  endLine: number;
  endCharacter: number;
  message: string;
}

/** Whether this language id maps to a TypeScript-family parser. */
function scriptKindFor(languageId: string, filePath: string): ts.ScriptKind | null {
  const ext = extensionOf(filePath);
  if (ext === 'tsx') return ts.ScriptKind.TSX;
  if (ext === 'jsx') return ts.ScriptKind.JSX;
  if (ext === 'ts' || ext === 'mts' || ext === 'cts') return ts.ScriptKind.TS;
  if (ext === 'js' || ext === 'mjs' || ext === 'cjs') return ts.ScriptKind.JS;
  // Fall back to language id for hosts that don't expose a useful extension.
  if (languageId === 'typescriptreact') return ts.ScriptKind.TSX;
  if (languageId === 'javascriptreact') return ts.ScriptKind.JSX;
  if (languageId === 'typescript') return ts.ScriptKind.TS;
  if (languageId === 'javascript') return ts.ScriptKind.JS;
  return null;
}

function extensionOf(filePath: string): string {
  const base = filePath.replace(/[?#].*$/, '');
  const idx = base.lastIndexOf('.');
  return idx >= 0 ? base.slice(idx + 1).toLowerCase() : '';
}

function checkTs(code: string, filePath: string, kind: ts.ScriptKind): SyntaxIssue[] {
  const fileName = filePath.split('/').pop() || 'result';
  const sourceFile = ts.createSourceFile(fileName, code, ts.ScriptTarget.Latest, true, kind);
  return sourceFile.parseDiagnostics.map((diagnostic) => {
    const start = diagnostic.start ?? 0;
    const length = diagnostic.length ?? 0;
    const startPos = diagnostic.file?.getLineAndCharacterOfPosition(start) ?? { line: 0, character: 0 };
    const endPos = diagnostic.file?.getLineAndCharacterOfPosition(start + length) ?? startPos;
    return {
      startLine: startPos.line,
      startCharacter: startPos.character,
      endLine: endPos.line,
      endCharacter: endPos.character,
      message: ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n'),
    };
  });
}

function checkJson(code: string): SyntaxIssue[] {
  try {
    JSON.parse(code);
    return [];
  } catch (error) {
    const position = positionFromJsonError(error);
    return [{
      startLine: position.line,
      startCharacter: position.character,
      endLine: position.line,
      endCharacter: position.character + 1,
      message: error instanceof Error ? error.message : String(error),
    }];
  }
}

function positionFromJsonError(error: unknown): { line: number; character: number } {
  const message = error instanceof Error ? error.message : '';
  // V8/WebKit: "at position 12 (line 1 column 13)"; others vary.
  const lineMatch = message.match(/line (\d+)/);
  const columnMatch = message.match(/column (\d+)/);
  if (lineMatch && columnMatch) {
    return { line: Number(lineMatch[1]) - 1, character: Number(columnMatch[1]) - 1 };
  }
  const posMatch = message.match(/position (\d+)/);
  if (posMatch) {
    const position = Number(posMatch[1]);
    // Without line info we can't map the flat offset back reliably; report at origin.
    return { line: 0, character: Math.max(0, position) };
  }
  return { line: 0, character: 0 };
}

/** Returns null when the language isn't supported by this checker. */
export function checkSyntax(languageId: string, filePath: string, code: string): SyntaxIssue[] | null {
  const kind = scriptKindFor(languageId, filePath);
  if (kind !== null) {
    return checkTs(code, filePath, kind);
  }
  if (languageId === 'json' || languageId === 'jsonc') {
    return checkJson(code);
  }
  return null;
}
