function checkJson(code: string): SyntaxIssue[] {
  try {
    JSON.parse(code);
    return [];
  } catch (error) {
    const position = positionFromJsonError(error);
    return [{
      startLine: position.line,
      startCharacter: position.character,
      endLine: position.line,
      endCharacter: position.character + 1,
      message: error instanceof Error ? error.message : String(error),
    }];
