function positionFromJsonError(error: unknown): { line: number; character: number } {
  const message = error instanceof Error ? error.message : '';
  // V8/WebKit: "at position 12 (line 1 column 13)"; others vary.
  const lineMatch = message.match(/line (\d+)/);
  const columnMatch = message.match(/column (\d+)/);
  if (lineMatch && columnMatch) {
    return { line: Number(lineMatch[1]) - 1, character: Number(columnMatch[1]) - 1 };
  }
  const posMatch = message.match(/position (\d+)/);
  if (posMatch) {
    const position = Number(posMatch[1]);
    // Without line info we can't map the flat offset back reliably; report at origin.
    return { line: 0, character: Math.max(0, position) };
  }
  return { line: 0, character: 0 };
}

