```ts
import * as ts from 'typescript';

/**
 * Self-contained syntax check of the merged result, run entirely in the webview so it
 * works identically in the VS Code panel and the Tauri desktop app — no host or
 * language-service round-trip required. TypeScript's parser reports precise multi-error
 * syntax diagnostics for TS/JS/TSX/JSX; JSON uses JSON.parse. Everything else returns
 * `null` ("no checker available").
 */

export interface SyntaxIssue {
  /** 0-based start position. */
  startLine: number;
  startCharacter: number;
  /** 0-based end position (exclusive). */
  endLine: number;
  endCharacter: number;
  message: string;
}

/** Returns the syntax issues in `code`, or `null` when this file type isn't supported. */
export function checkSyntax(languageId: string, filePath: string, code: string): SyntaxIssue[] | null {
  const scriptKind = scriptKindFor(languageId, filePath);
  if (scriptKind !== null) {
    return checkTypeScript(code, filePath, scriptKind);
  }
  if (languageId === 'json') {
    return checkJson(code);
  }
  return null;
}

function scriptKindFor(languageId: string, filePath: string): ts.ScriptKind | null {
  const ext = extensionOf(filePath);
  if (ext === 'tsx') return ts.ScriptKind.TSX;
  if (ext === 'jsx') return ts.ScriptKind.JSX;
  if (ext === 'ts' || ext === 'mts' || ext === 'cts') return ts.ScriptKind.TS;
  if (ext === 'js' || ext === 'mjs' || ext === 'cjs') return ts.ScriptKind.JS;
  if (languageId === 'typescriptreact') return ts.ScriptKind.TSX;
  if (languageId === 'javascriptreact') return ts.ScriptKind.JSX;
  if (languageId === 'typescript') return ts.ScriptKind.TS;
  if (languageId === 'javascript') return ts.ScriptKind.JS;
  return null;
}

function extensionOf(filePath: string): string {
  const clean = filePath.replace(/[?#].*$/, '');
  const slash = clean.lastIndexOf('/');
  const dot = clean.lastIndexOf('.');
  return dot > slash ? clean.slice(dot + 1).toLowerCase() : '';
}

function checkTypeScript(code: string, filePath: string, scriptKind: ts.ScriptKind): SyntaxIssue[] {
  const fileName = filePath.split('/').pop() || 'result';
  const result = ts.transpileModule(code, {
    fileName,
    reportDiagnostics: true,
    compilerOptions: {
      target: ts.ScriptTarget.Latest,
      jsx: ts.JsxEmit.Preserve,
      allowJs: true,
    },
  });
  return (result.diagnostics ?? []).map((diagnostic) =>
    toIssue(code, diagnostic.start ?? 0, diagnostic.length ?? 0, diagnostic),
  );
}

function checkJson(code: string): SyntaxIssue[] {
  try {
    JSON.parse(code);
    return [];
  } catch (error) {
    return [jsonErrorToIssue(error)];
  }
}

function toIssue(code: string, start: number, length: number, diagnostic: ts.Diagnostic): SyntaxIssue {
  const message = ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n');
  const end = Math.max(start + length, start + 1);
  const startPos = lineColumnAt(code, start);
  const endPos = lineColumnAt(code, end);
  return {
    startLine: startPos.line,
    startCharacter: startPos.character,
    endLine: endPos.line,
    endCharacter: endPos.character,
    message,
  };
}

