    return checkTypeScript(code, fileNameOf(filePath));
  }
  if (languageId === 'json') {
    return checkJson(code);
  }
  return null;
}

function isTypeScriptLike(languageId: string, filePath: string): boolean {
  const ext = extensionOf(filePath);
  if (ext === 'ts' || ext === 'tsx' || ext === 'js' || ext === 'jsx') {
    return true;
